#include "Shortcuts.h"
static void testShortcuts(const File& root){
    ShortcutSettings settings;expect(shortcutCommands().size()==73&&validateShortcuts(settings).wasOk(),"all factory shortcuts are valid and unique");
    for(const auto& command:shortcutCommands()){expect(shortcutCommand(command.id)==&command,"shortcut stable ID resolves");String key;expect(canonicalShortcut(command.defaultKey,key).wasOk()&&key==command.defaultKey,"factory shortcut canonical round trip");if(key.isNotEmpty())expect(findShortcut(settings,key,false)==command.id,"factory shortcut resolves to its exact command");}
    String key="keep";expect(canonicalShortcut(" alt + ctrl + shift + j ",key).wasOk()&&key=="Ctrl+Alt+Shift+J","shortcut parser canonicalizes modifier order case and spacing");
    for(auto invalid:{"Escape","Ctrl+Ctrl+J","Ctrl++J","J+Ctrl","Ctrl+","Ctrl+F13","Command+Q","Ctrl+;","Alt+F4","Alt+Tab","Ctrl+Alt+Delete","Alt+Shift+F4","Ctrl+Alt+Tab","Alt+Space","Ctrl+Alt+Shift+Delete"}){key="untouched";expect(canonicalShortcut(invalid,key).failed()&&key=="untouched","invalid or system chord leaves output untouched");}
    expect(setShortcut(settings,"project.save","Ctrl+J").wasOk()&&findShortcut(settings,"Ctrl+J",true)=="project.save"&&findShortcut(settings,"Ctrl+S",true).isEmpty(),"remapping releases the original binding");auto saved=settings;
    expect(setShortcut(settings,"project.open","Ctrl+J").failed()&&settings==saved,"conflicting binding rejects atomically");expect(setShortcut(settings,"project.open","Ctrl+Shift+H").failed()&&settings==saved,"window recovery key cannot be stolen");expect(setShortcut(settings,"window.recover","").failed()&&settings==saved,"window recovery cannot be disabled");
    expect(setShortcut(settings,"project.open","Q").failed()&&setShortcut(settings,"project.open","Shift+Q").failed(),"global commands cannot steal piano letters with Shift or no modifiers");expect(setShortcut(settings,"project.open","Ctrl+Alt+J").wasOk(),"exact modifier combinations are distinct");
    expect(setShortcut(settings,"project.save","").wasOk()&&shortcutBinding(settings,"project.save").isEmpty(),"empty override disables an action without reinstating factory key");expect(setShortcut(settings,"project.save","Ctrl+S").wasOk()&&!settings.overrides.count("project.save"),"restoring default removes the override");expect(setShortcut(settings,"tools.draw","G").wasOk()&&findShortcut(settings,"G",false)=="tools.draw"&&findShortcut(settings,"G",true).isEmpty(),"typing-off commands retain their context when remapped");
    expect(setShortcut(settings,"project.versions","Ctrl+Shift+J").wasOk(),"unassigned commands can receive a shortcut");
    auto file=root.getChildFile("shortcut-core/shortcuts.json");expect(saveShortcuts(file,settings).wasOk(),"keyboard shortcut preferences save atomically");ShortcutSettings loaded;expect(loadShortcuts(file,loaded).wasOk()&&loaded==settings,"shortcut overrides and disabled/default distinctions persist");auto token=shortcutFileToken(file);file.appendText("\n");expect(shortcutFileToken(file)!=token,"shortcut content token detects changed preferences");
    auto legacy=root.getChildFile("shortcut-core/pre-history.json");legacy.replaceWithText(R"({"schema":1,"overrides":{"project.save":"Ctrl+Alt+H","tools.draw":"G"}})");ShortcutSettings migrated;
    expect(loadShortcuts(legacy,migrated).wasOk()&&shortcutBinding(migrated,"project.save")=="Ctrl+Alt+H"&&shortcutBinding(migrated,"tools.draw")=="G"&&shortcutBinding(migrated,"edit.history").isEmpty(),"old custom shortcut ownership is retained when the new history chord conflicts");
    expect(saveShortcuts(legacy,migrated).wasOk()&&loadShortcuts(legacy,migrated).wasOk()&&shortcutBinding(migrated,"edit.history").isEmpty(),"migrated disabled history shortcut persists on the next deliberate preference save");
    auto stable=loaded;file.replaceWithText("{broken");expect(loadShortcuts(file,loaded).failed()&&loaded==stable,"corrupt shortcut file preserves current preferences");
    for(auto json:{R"({"schema":2,"overrides":{}})",R"({"schema":1,"overrides":{"missing":"Ctrl+J"}})",R"({"schema":1,"overrides":{"project.save":42}})",R"({"schema":1,"overrides":{"project.save":"Ctrl+O"}})",R"({"schema":1,"overrides":{"project.save":"ctrl+j"}})",R"({"schema":1,"overrides":{"window.recover":"Ctrl+Shift+H"}})"}){file.replaceWithText(json);expect(loadShortcuts(file,loaded).failed()&&loaded==stable,"invalid shortcut schema ID type conflict or fixed binding rejects atomically");}
    file.replaceWithText(String::repeatedString("x",65537));expect(shortcutFileToken(file)=="unavailable"&&loadShortcuts(file,loaded).failed()&&loaded==stable,"oversized shortcut file is bounded and leaves preferences intact");
    ShortcutSettings absent=stable;expect(loadShortcuts(root.getChildFile("shortcut-core/missing.json"),absent).wasOk()&&absent.overrides.empty(),"missing local preferences select factory defaults");
    auto invalid=settings;invalid.overrides["missing"]="Ctrl+J";auto original=file.loadFileAsString();expect(saveShortcuts(file,invalid).failed()&&file.loadFileAsString()==original,"invalid save never replaces preference file");
    auto exchange=root.getChildFile("shortcut-core/portable.pulseshortcuts");expect(saveShortcuts(exchange,settings).wasOk(),"portable shortcut draft exports without changing active preferences");ShortcutSettings imported;expect(loadShortcuts(exchange,imported).wasOk()&&imported==settings,"portable shortcut import restores complete overrides");expect(saveShortcuts(exchange,{}).wasOk()&&loadShortcuts(exchange,imported).wasOk()&&imported.overrides.empty(),"portable factory reset import clears prior draft overrides");
    auto block=root.getChildFile("shortcut-core/blocked");block.replaceWithText("file blocks directory");expect(saveShortcuts(block.getChildFile("shortcuts.json"),settings).failed(),"shortcut destination write failure reports an error");
}
